["adjectives"]}],"lessons":[{"id":"zh-a1-u11-l01","unit_id":"zh-a1-u11","position":1,"title_es":"我喜欢…","objective_es":"Decir lo que te gusta y lo que no.","intro":{"explanation":"喜欢 (xǐhuan) es «gustar», pero se usa como un verbo común: 我喜欢猫 es «me gustan los gatos» (literalmente «yo gusto gatos»). Para negar, 不 va antes: 我不喜欢…","examples":[{"target":"我喜欢猫。","base":"Me gustan los gatos."},{"target":"我不喜欢牛奶。","base":"No me gusta la leche."}]},"takeaways":["Decís lo que te gusta con 喜欢.","Negás con 不喜欢."]},{"id":"zh-a1-u11-l02","unit_id":"zh-a1-u11","position":2,"title_es":"唱歌和跳舞","objective_es":"Hablar de pasatiempos.","intro":{"explanation":"Muchas actividades son verbo + cosa: 唱歌 «cantar» (cantar canciones), 跳舞 «bailar», 踢足球 «jugar al fútbol» (patear la pelota). Van después de 喜欢: 我喜欢跳舞.","examples":[{"target":"我喜欢跳舞。","base":"Me gusta bailar."},{"target":"他非常喜欢踢足球。","base":"A él le encanta jugar al fútbol."}]},"takeaways":["Nombrás pasatiempos.","Decís que algo te encanta con 非常喜欢."]},{"id":"zh-a1-u11-rev1","unit_id":"zh-a1-u11","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «我喜欢…» y «唱歌和跳舞».","intro":null,"takeaways":[]},{"id":"zh-a1-u11-l03","unit_id":"zh-a1-u11","position":4,"title_es":"我会游泳","objective_es":"Decir lo que sabés hacer.","intro":{"explanation":"会 (huì) es «saber hacer» algo que se aprende: nadar, manejar, un idioma. Va antes del verbo: 我会游泳. Se niega con 不, que antes del cuarto tono de 会 se dice bú: 我不会开车 (wǒ bú huì kāichē).","examples":[{"target":"我会游泳。","base":"Sé nadar."},{"target":"你会说中文吗？","base":"¿Sabés hablar chino?"}]},"takeaways":["Decís lo que sabés hacer con 会.","Decís lo que no sabés con 不会."]},{"id":"zh-a1-u11-l04","unit_id":"zh-a1-u11","position":5,"title_es":"你能来吗？","objective_es":"Decir si podés hacer algo.","intro":{"explanation":"能 (néng) es «poder»: si es posible en ese momento. 我今天不能去 «hoy no puedo ir». Compará: 我会游泳 (sé nadar) y 今天我不能游泳 (hoy no puedo nadar).","examples":[{"target":"明天你能来吗？","base":"¿Mañana podés venir?"},{"target":"今天我不能去。","base":"Hoy no puedo ir."}]},"takeaways":["Preguntás si alguien puede con 能…吗？","Distinguís 会 (saber) y 能 (poder)."]},{"id":"zh-a1-u11-rev2","unit_id":"zh-a1-u11","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «我会游泳» y «你能来吗？».","intro":null,"takeaways":[]},{"id":"zh-a1-u11-l05","unit_id":"zh-a1-u11","position":7,"title_es":"我很忙","objective_es":"Decir cómo estás y describir cosas.","intro":{"explanation":"Los adjetivos van con 很 y sin 是: 我很忙 «estoy (muy) ocupado/a», 这个房间很大 «esta habitación es grande». 很 casi no suma «muy»: es lo normal. Para «muchísimo», 非常: 我非常累.","examples":[{"target":"我今天很忙。","base":"Hoy estoy ocupado/a."},{"target":"我的房间很小。","base":"Mi habitación es chica."}]},"takeaways":["Decís cómo estás con 很 + adjetivo.","Describís cosas como grandes o chicas."]},{"id":"zh-a1-u11-listen","unit_id":"zh-a1-u11","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"zh-a1-u11-words","unit_id":"zh-a1-u11","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"zh-a1-u11-final","unit_id":"zh-a1-u11","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Gustos y habilidades».","intro":null,"takeaways":[]}],"exercises":[{"id":"zh-a1-u11-l01-e01","lesson_id":"zh-a1-u11-l01","position":1,"type":"translation_choice","skill":"vocabulary","prompt_es":"¿Qué significa «喜欢»?","payload":{"type":"translation_choice","word":"喜欢","options":["gustar","querer (pedir)","tener","saber (hacer algo)"]},"answer":"gustar","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":12,"words":["zh-xihuan"]},{"id":"zh-a1-u11-l01-e02","lesson_id":"zh-a1-u11-l01","position":2,"type":"listen_choice","skill":"listening","prompt_es":"Escuchá y elegí el tono correcto","payload":{"type":"listen_choice","